pub(crate) fn read8(address: u64) -> Option<u8> {
    let rva = address.checked_sub(super::end_source60_core::LIB_BASE)?;
    let page = rva & !0xfff;
    let offset = (rva & 0xfff) as usize;
    let table: &[u8; 4096] = match page {
        0x06000 => &PAGE_06000,
        0x14000 => &PAGE_14000,
        0x24000 => &PAGE_24000,
        0x44000 => &PAGE_44000,
        0xcd000 => &PAGE_CD000,
        _ => return None,
    };
    Some(table[offset])
}
